def transform(grid):
    h, w = len(grid), len(grid[0])
    points = [(r, c, grid[r][c])
              for r in range(h) for c in range(w) if grid[r][c] != 0]

    if not points:
        return [row[:] for row in grid]

    projections = [
        lambda r, c: r,
        lambda r, c: c,
        lambda r, c: r + c,
        lambda r, c: c - r,
    ]
    candidates = []

    for project in projections:
        by_key = {}
        valid = True
        for r, c, color in points:
            key = project(r, c)
            if key in by_key and by_key[key] != color:
                valid = False
                break
            by_key[key] = color
        if not valid:
            continue

        for period in range(1, 2 * (h + w) + 2):
            by_residue = {}
            for key, color in by_key.items():
                residue = key % period
                if residue in by_residue and by_residue[residue] != color:
                    valid = False
                    break
                by_residue[residue] = color
            if not valid:
                valid = True
                continue
            if len(by_residue) == period:
                candidates.append((period, project, by_residue, len(by_key)))
                break

    if not candidates:
        return [row[:] for row in grid]

    _, project, pattern, _ = min(candidates, key=lambda item: (item[0], -item[3]))
    return [[pattern[project(r, c) % len(pattern)] for c in range(w)]
            for r in range(h)]
